// Some portions generated by Claude
import type { CSSProperties, Ref } from "react";
import { DETAILS_ITEM_LIMIT } from "./explorer-config.ts";
import { compactTerm } from "./graph-terms.ts";
import type { GraphNode } from "./graph-types.ts";
import { nodeVisual, typeVisual } from "./graph-visuals.ts";
import { Icon } from "./icons.tsx";
import type { NodeDetails } from "./node-details.ts";

export type NodeDetailsCardProps = {
  node: GraphNode;
  details: NodeDetails;
  /** The Explore page of the node, for IRIs. */
  exploreHref: string;
  expanding: boolean;
  /** Whether the node is on the canvas (only drawn nodes can be pinned). */
  drawn: boolean;
  cardRef: Ref<HTMLElement>;
  onClose: () => void;
  onCopy: (text: string) => void;
  onExpand: () => void;
  onTogglePin: () => void;
  onHide: () => void;
  onFollow: (nodeId: string) => void;
  /** Opens the card of one of the node's statements (subject, predicate, object). */
  onStatement: (source: string, predicate: string, target: string) => void;
  /** What the node says about statements (RDF 1.2 triple terms): "reifies" Alice knows Bob. */
  statementLinks: ReadonlyArray<{ id: string; label: string; text: string }>;
  onStatementLink: (linkId: string) => void;
};

/** The button beside a value or link that opens that statement's card; shown on hover and keyboard focus. */
function StatementButton({ label, onClick }: { label: string; onClick: () => void }) {
  return (
    <button
      type="button"
      className="node-details-statement"
      aria-label={`Statement: ${label}`}
      title={`About “${label}”`}
      onClick={onClick}
    >
      <Icon name="statement" />
    </button>
  );
}

/** The selected node's card over the canvas: types, identifier, actions, values and links. */
export function NodeDetailsCard({
  node,
  details,
  exploreHref,
  expanding,
  drawn,
  cardRef,
  onClose,
  onCopy,
  onExpand,
  onTogglePin,
  onHide,
  onFollow,
  onStatement,
  statementLinks,
  onStatementLink,
}: NodeDetailsCardProps) {
  return (
    <aside
      ref={cardRef}
      className="node-details"
      aria-label={`Details of ${node.label}`}
      onClick={(event) => event.stopPropagation()}
      onPointerDown={(event) => event.stopPropagation()}
      onWheel={(event) => event.stopPropagation()}
    >
      <header className="node-details-header">
        <div>
          {details.types.length ? (
            <ul className="node-details-types" aria-label="Types">
              {details.types.map((type) => (
                <li
                  key={type.id}
                  title={type.id}
                  style={{ "--type-color": typeVisual(type.id).stroke } as CSSProperties}
                >
                  {type.label}
                </li>
              ))}
            </ul>
          ) : (
            <p className="node-details-kind">
              {node.kind === "literal" ? "Value" : node.kind === "blank" ? "Blank node" : "Resource"}
            </p>
          )}
          <h3>{node.kind === "literal" ? node.termValue ?? node.label : node.label}</h3>
        </div>
        <button
          className="workbench-action workbench-action--ghost workbench-action--icon"
          type="button"
          aria-label="Close details"
          title="Close details"
          onClick={onClose}
        >
          <Icon name="close" />
        </button>
      </header>
      {node.kind !== "literal" ? (
        <div className="node-details-identifier">
          <code title={node.id}>{node.id}</code>
          <button
            className="workbench-action workbench-action--ghost workbench-action--icon"
            type="button"
            aria-label="Copy identifier"
            title="Copy identifier"
            onClick={() => onCopy(node.id)}
          >
            <Icon name="copy" />
          </button>
        </div>
      ) : null}
      <div className="node-details-actions">
        {node.kind === "iri" ? (
          <button
            className="workbench-action workbench-action--primary"
            type="button"
            title="Load the nodes this one links to and from (double-click a node does the same)"
            disabled={expanding}
            onClick={onExpand}
          >
            <Icon name="expand" />
            {expanding ? "Expanding…" : "Expand"}
          </button>
        ) : null}
        {node.kind === "iri" ? (
          <a
            className="workbench-action workbench-action--secondary"
            href={exploreHref}
            title="Every statement about this resource, on the Explore page"
          >
            <Icon name="explore" />
            Explore
          </a>
        ) : null}
        {drawn ? (
          <button
            className="workbench-action workbench-action--secondary workbench-action--icon"
            type="button"
            aria-label={node.pinned ? "Unpin" : "Pin in place"}
            title={node.pinned ? "Unpin" : "Pin in place"}
            aria-pressed={Boolean(node.pinned)}
            onClick={onTogglePin}
          >
            <Icon name="pin" />
          </button>
        ) : null}
        <button
          className="workbench-action workbench-action--secondary workbench-action--icon"
          type="button"
          aria-label="Hide from the graph"
          title="Hide from the graph"
          onClick={onHide}
        >
          <Icon name="hide" />
        </button>
      </div>
      {details.values.length || details.links.length || statementLinks.length ? (
        <dl className="node-details-body">
          {details.values.map((group) => (
            <div key={`value ${group.predicate}`} className="node-details-row">
              <dt title={group.predicate}>{group.label}</dt>
              <dd>
                {group.items.slice(0, DETAILS_ITEM_LIMIT).map((item) => (
                  <span key={item.id} className="node-details-item">
                    <span
                      className="node-details-value"
                      title={item.datatype ? compactTerm(item.datatype, 48) : undefined}
                    >
                      {item.termValue ?? item.label}
                      {item.language ? <small>{item.language}</small> : null}
                    </span>
                    <StatementButton
                      label={`${node.label} ${group.label} ${item.termValue ?? item.label}`}
                      onClick={() => onStatement(node.id, group.predicate, item.id)}
                    />
                  </span>
                ))}
                {group.items.length > DETAILS_ITEM_LIMIT ? (
                  <small className="node-details-more">+{group.items.length - DETAILS_ITEM_LIMIT}</small>
                ) : null}
              </dd>
            </div>
          ))}
          {details.links.map((group) => (
            <div key={`${group.direction} ${group.predicate}`} className={group.direction === "incoming" ? "node-details-row is-incoming" : "node-details-row is-outgoing"}>
              <dt title={group.predicate}>
                {group.direction === "incoming" ? <span aria-label="Incoming:">← </span> : null}
                {group.label}
              </dt>
              <dd>
                {group.items.slice(0, DETAILS_ITEM_LIMIT).map((item) => {
                  const outgoing = group.direction === "outgoing";
                  const statement = outgoing ? `${node.label} ${group.label} ${item.label}` : `${item.label} ${group.label} ${node.label}`;
                  return (
                    <span key={item.id} className="node-details-item">
                      <button
                        type="button"
                        className="node-details-link"
                        title={statement}
                        style={{ "--node-color": nodeVisual(item).stroke } as CSSProperties}
                        onClick={() => onFollow(item.id)}
                      >
                        {item.label}
                      </button>
                      <StatementButton
                        label={statement}
                        onClick={() =>
                          outgoing ? onStatement(node.id, group.predicate, item.id) : onStatement(item.id, group.predicate, node.id)
                        }
                      />
                    </span>
                  );
                })}
                {group.items.length > DETAILS_ITEM_LIMIT ? (
                  <small className="node-details-more">+{group.items.length - DETAILS_ITEM_LIMIT}</small>
                ) : null}
              </dd>
            </div>
          ))}
          {statementLinks.map((link) => (
            <div key={link.id} className="node-details-row">
              <dt>{link.label}</dt>
              <dd>
                <button type="button" className="node-details-link is-statement" title={link.text} onClick={() => onStatementLink(link.id)}>
                  <Icon name="statement" />
                  {link.text}
                </button>
              </dd>
            </div>
          ))}
        </dl>
      ) : null}
    </aside>
  );
}
